CREATE OR REPLACE FUNCTION public.complete_admin_manual_experience_payout_atomic(p_request_key uuid, p_host_id uuid, p_settlement_type text, p_expected_current_booking_amount integer, p_legacy_amount integer, p_reason text, p_legacy_source_reference text, p_transfer_reference text, p_paid_by_admin_id uuid, p_paid_by_admin_email text)
 RETURNS TABLE(manual_payout_id uuid, request_key uuid, host_id uuid, booking_count integer, current_booking_amount integer, legacy_amount integer, total_paid_amount integer, paid_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing public.admin_manual_payouts%ROWTYPE;
  v_booking_ids text[];
  v_booking_snapshot jsonb;
  v_current_amount integer;
  v_booking_count integer;
  v_updated_count integer;
  v_paid_at timestamptz := clock_timestamp();
  v_manual_payout_id uuid;
  v_bank_name text;
  v_account_number text;
  v_account_holder text;
BEGIN
  IF p_request_key IS NULL OR p_host_id IS NULL OR p_paid_by_admin_id IS NULL THEN
    RAISE EXCEPTION '필수 식별값이 누락되었습니다.';
  END IF;

  IF p_settlement_type NOT IN ('host_exit_final', 'legacy_carryover') THEN
    RAISE EXCEPTION '지원하지 않는 수동 정산 유형입니다.';
  END IF;

  IF length(btrim(COALESCE(p_reason, ''))) = 0
    OR length(btrim(COALESCE(p_transfer_reference, ''))) = 0
    OR length(btrim(COALESCE(p_paid_by_admin_email, ''))) = 0
  THEN
    RAISE EXCEPTION '사유, 이체 참조값, 관리자 정보는 필수입니다.';
  END IF;

  IF length(btrim(p_reason)) > 1000
    OR length(btrim(p_transfer_reference)) > 500
    OR length(btrim(COALESCE(p_legacy_source_reference, ''))) > 500
  THEN
    RAISE EXCEPTION '정산 사유 또는 참조값이 너무 깁니다.';
  END IF;

  IF p_settlement_type = 'host_exit_final' AND COALESCE(p_legacy_amount, 0) <> 0 THEN
    RAISE EXCEPTION '활동 종료 정산에는 legacy 금액을 포함할 수 없습니다.';
  END IF;

  IF p_settlement_type = 'legacy_carryover' AND (
    COALESCE(p_legacy_amount, 0) <= 0
    OR length(btrim(COALESCE(p_legacy_source_reference, ''))) = 0
  ) THEN
    RAISE EXCEPTION '이전 사이트 이월액과 출처는 필수입니다.';
  END IF;

  -- Serialize manual payout attempts for the same host, including different request keys.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_host_id::text, 0));

  SELECT * INTO v_existing
  FROM public.admin_manual_payouts
  WHERE admin_manual_payouts.request_key = p_request_key;

  IF FOUND THEN
    IF v_existing.host_id <> p_host_id
      OR v_existing.settlement_type <> p_settlement_type
      OR v_existing.current_booking_amount <> p_expected_current_booking_amount
      OR v_existing.legacy_amount <> COALESCE(p_legacy_amount, 0)
      OR v_existing.reason <> btrim(p_reason)
      OR COALESCE(v_existing.legacy_source_reference, '') <> COALESCE(NULLIF(btrim(p_legacy_source_reference), ''), '')
      OR v_existing.transfer_reference <> btrim(p_transfer_reference)
    THEN
      RAISE EXCEPTION '같은 request key가 다른 정산 내용으로 재사용되었습니다.' USING ERRCODE = 'P0001';
    END IF;

    RETURN QUERY SELECT
      v_existing.id,
      v_existing.request_key,
      v_existing.host_id,
      cardinality(v_existing.booking_ids),
      v_existing.current_booking_amount,
      v_existing.legacy_amount,
      v_existing.total_paid_amount,
      v_existing.paid_at;
    RETURN;
  END IF;

  SELECT ha.bank_name, ha.account_number, ha.account_holder
  INTO v_bank_name, v_account_number, v_account_holder
  FROM public.host_applications AS ha
  WHERE ha.user_id = p_host_id
  ORDER BY ha.created_at DESC
  LIMIT 1;

  IF length(btrim(COALESCE(v_bank_name, ''))) = 0
    OR length(btrim(COALESCE(v_account_number, ''))) = 0
    OR length(btrim(COALESCE(v_account_holder, ''))) = 0
  THEN
    RAISE EXCEPTION '호스트 지급 계좌가 등록되어 있지 않습니다.';
  END IF;

  -- Lock every current experience liability for this host before validating or updating it.
  PERFORM b.id
  FROM public.bookings AS b
  JOIN public.experiences AS e ON e.id = b.experience_id
  WHERE e.host_id = p_host_id
    AND b.payout_status IS DISTINCT FROM 'paid'
    AND b.status IN ('completed', 'COMPLETED', 'cancelled', 'CANCELLED')
  ORDER BY b.id
  FOR UPDATE OF b;

  IF EXISTS (
    SELECT 1
    FROM public.bookings AS b
    JOIN public.experiences AS e ON e.id = b.experience_id
    WHERE e.host_id = p_host_id
      AND b.payout_status IS DISTINCT FROM 'paid'
      AND b.status IN ('completed', 'COMPLETED', 'cancelled', 'CANCELLED')
      AND (
        b.payout_status IS DISTINCT FROM 'pending'
        OR b.host_payout_amount IS NULL
        OR b.host_payout_amount < 0
        OR (
          b.host_payout_amount = 0
          AND b.status NOT IN ('cancelled', 'CANCELLED')
        )
        OR b.solo_guarantee_refund_status IN ('processing', 'pending_manual', 'failed')
      )
  ) THEN
    RAISE EXCEPTION '지급액 또는 환불 상태 확인이 필요한 예약이 포함되어 있습니다.';
  END IF;

  SELECT
    array_agg(b.id::text ORDER BY b.id),
    jsonb_agg(
      jsonb_build_object(
        'id', b.id,
        'order_id', b.order_id,
        'experience_id', b.experience_id,
        'status', b.status,
        'payout_status', b.payout_status,
        'host_payout_amount', b.host_payout_amount,
        'date', b.date,
        'time', b.time
      ) ORDER BY b.id
    ),
    COALESCE(sum(b.host_payout_amount), 0)::integer,
    count(*)::integer
  INTO v_booking_ids, v_booking_snapshot, v_current_amount, v_booking_count
  FROM public.bookings AS b
  JOIN public.experiences AS e ON e.id = b.experience_id
  WHERE e.host_id = p_host_id
    AND b.payout_status = 'pending'
    AND b.status IN ('completed', 'COMPLETED', 'cancelled', 'CANCELLED')
    AND b.host_payout_amount > 0;

  IF v_booking_count = 0 OR v_current_amount <= 0 THEN
    RAISE EXCEPTION '정산할 신규 사이트 체험 미정산액이 없습니다.';
  END IF;

  IF v_current_amount >= 100000 THEN
    RAISE EXCEPTION '10만원 이상 금액은 기존 일반 정산을 이용해야 합니다.';
  END IF;

  IF p_expected_current_booking_amount IS NULL OR p_expected_current_booking_amount <> v_current_amount THEN
    RAISE EXCEPTION '미정산 금액이 변경되었습니다. 새로고침 후 다시 확인해 주세요.';
  END IF;

  IF p_settlement_type = 'host_exit_final' THEN
    IF EXISTS (
      SELECT 1
      FROM public.bookings AS b
      JOIN public.experiences AS e ON e.id = b.experience_id
      WHERE e.host_id = p_host_id
        AND b.status IN ('PAID', 'confirmed')
    ) THEN
      RAISE EXCEPTION '미래 또는 진행 중 체험 예약이 있어 활동 종료 정산을 할 수 없습니다.';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.service_bookings AS sb
      WHERE sb.host_id = p_host_id
        AND (
          sb.status IN ('PAID', 'confirmed')
          OR (sb.status = 'completed' AND sb.payout_status IS DISTINCT FROM 'paid')
        )
    ) THEN
      RAISE EXCEPTION '진행 중이거나 미정산인 서비스가 있어 활동 종료 정산을 할 수 없습니다.';
    END IF;
  END IF;

  UPDATE public.bookings AS b
  SET payout_status = 'paid', payout_paid_at = v_paid_at
  WHERE b.id::text = ANY(v_booking_ids)
    AND b.payout_status = 'pending'
    AND b.status IN ('completed', 'COMPLETED', 'cancelled', 'CANCELLED');

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> v_booking_count THEN
    RAISE EXCEPTION '정산 대상이 동시에 변경되었습니다. 새로고침 후 다시 시도해 주세요.';
  END IF;

  INSERT INTO public.admin_manual_payouts (
    request_key, host_id, settlement_type, booking_ids, booking_snapshot,
    current_booking_amount, legacy_amount, total_paid_amount, reason,
    legacy_source_reference, transfer_reference, bank_name, account_number,
    account_holder, paid_by_admin_id, paid_by_admin_email, paid_at
  ) VALUES (
    p_request_key, p_host_id, p_settlement_type, v_booking_ids, v_booking_snapshot,
    v_current_amount, COALESCE(p_legacy_amount, 0), v_current_amount + COALESCE(p_legacy_amount, 0),
    btrim(p_reason), NULLIF(btrim(p_legacy_source_reference), ''), btrim(p_transfer_reference),
    btrim(v_bank_name), btrim(v_account_number), btrim(v_account_holder),
    p_paid_by_admin_id, btrim(p_paid_by_admin_email), v_paid_at
  )
  RETURNING id INTO v_manual_payout_id;

  RETURN QUERY SELECT
    v_manual_payout_id,
    p_request_key,
    p_host_id,
    v_booking_count,
    v_current_amount,
    COALESCE(p_legacy_amount, 0),
    v_current_amount + COALESCE(p_legacy_amount, 0),
    v_paid_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_experience_booking_if_due_atomic(p_booking_id text)
 RETURNS TABLE(booking_id text, order_id text, user_id uuid, already_processed boolean, not_due boolean, completed boolean, notification_created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_experience_title TEXT;
  v_experience_host_id UUID;
  v_experience_duration INTEGER;
  v_due_at TIMESTAMPTZ;
  v_tour_end_at TIMESTAMPTZ;
  v_review_requests_due BOOLEAN := FALSE;
  v_notification_created BOOLEAN := FALSE;
BEGIN
  SELECT *
  INTO v_booking
  FROM public.bookings AS b
  WHERE b.id = trim(p_booking_id)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXP_COMPLETE_NOT_FOUND: experience booking not found';
  END IF;

  IF lower(COALESCE(v_booking.status, '')) = 'completed' THEN
    RETURN QUERY
    SELECT v_booking.id, COALESCE(v_booking.order_id, v_booking.id),
      v_booking.user_id::UUID, TRUE, FALSE, FALSE, FALSE;
    RETURN;
  END IF;

  IF COALESCE(v_booking.status, '') NOT IN ('PAID', 'confirmed') THEN
    RAISE EXCEPTION 'EXP_COMPLETE_INVALID_STATUS: booking status must be PAID, confirmed, or completed';
  END IF;

  IF v_booking.date IS NULL THEN
    RETURN QUERY
    SELECT v_booking.id, COALESCE(v_booking.order_id, v_booking.id),
      v_booking.user_id::UUID, FALSE, TRUE, FALSE, FALSE;
    RETURN;
  END IF;

  -- Preserve the existing start-time completion contract, including its
  -- missing-time 00:00 fallback. Only review notifications use strict time.
  v_due_at := (
    (v_booking.date::text || ' ' || COALESCE(NULLIF(v_booking.time, ''), '00:00'))::timestamp
    AT TIME ZONE 'Asia/Seoul'
  );

  IF v_due_at >= now() THEN
    RETURN QUERY
    SELECT v_booking.id, COALESCE(v_booking.order_id, v_booking.id),
      v_booking.user_id::UUID, FALSE, TRUE, FALSE, FALSE;
    RETURN;
  END IF;

  SELECT COALESCE(e.title, '체험'), e.host_id, e.duration
  INTO v_experience_title, v_experience_host_id, v_experience_duration
  FROM public.experiences AS e
  WHERE e.id = v_booking.experience_id;

  IF trim(COALESCE(v_booking.time, '')) ~ '^([01]?[0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' THEN
    v_tour_end_at := (
      (v_booking.date::text || ' ' || trim(v_booking.time))::timestamp
      AT TIME ZONE 'Asia/Seoul'
    ) + make_interval(hours => CASE WHEN v_experience_duration > 0 THEN v_experience_duration ELSE 2 END);
    v_review_requests_due := v_tour_end_at <= now();
  END IF;

  UPDATE public.bookings AS b
  SET status = 'completed'
  WHERE b.id = v_booking.id
    AND b.status IN ('PAID', 'confirmed');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'EXP_COMPLETE_UPDATE_CONFLICT: booking status changed before completion';
  END IF;

  IF
    v_review_requests_due
    AND v_booking.user_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.reviews AS r
      WHERE r.booking_id = v_booking.id
    )
  THEN
    INSERT INTO public.notifications (
      user_id, type, title, message, link, is_read, created_at, booking_id
    )
    VALUES (
      v_booking.user_id,
      'review_request',
      '후기를 남겨주세요!',
      format('''%s'' 어떠셨나요? 소중한 후기를 남겨주세요.', COALESCE(v_experience_title, '체험')),
      '/guest/trips',
      FALSE,
      now(),
      v_booking.id
    )
    ON CONFLICT (booking_id) WHERE type = 'review_request' AND booking_id IS NOT NULL
    DO NOTHING;

    v_notification_created := FOUND;
  END IF;

  IF
    v_review_requests_due
    AND v_booking.user_id IS NOT NULL
    AND v_experience_host_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.guest_reviews AS gr
      WHERE gr.booking_id = v_booking.id
        AND gr.host_id = v_experience_host_id
    )
  THEN
    INSERT INTO public.notifications (
      user_id, type, title, message, link, is_read, created_at, booking_id
    )
    VALUES (
      v_experience_host_id,
      'guest_review_request',
      '게스트 평가를 남겨주세요',
      format('''%s'' 체험의 게스트 평가를 남겨주세요.', COALESCE(v_experience_title, '체험')),
      '/host/dashboard?tab=reservations',
      FALSE,
      now(),
      v_booking.id
    )
    ON CONFLICT (booking_id) WHERE type = 'guest_review_request' AND booking_id IS NOT NULL
    DO NOTHING;
  END IF;

  RETURN QUERY
  SELECT v_booking.id, COALESCE(v_booking.order_id, v_booking.id),
    v_booking.user_id::UUID, FALSE, FALSE, TRUE, v_notification_created;
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_experience_bank_payment_atomic(p_booking_id text)
 RETURNS TABLE(outcome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_total_experience numeric;
  v_base_price numeric;
  v_host_payout integer;
  v_platform_revenue integer;
  v_refund_liability integer;
  v_solo_net integer;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'BANK_CONFIRM_FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_booking
    FROM public.bookings
   WHERE id = p_booking_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANK_CONFIRM_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF lower(coalesce(v_booking.payment_method, '')) <> 'bank' THEN
    RAISE EXCEPTION 'BANK_CONFIRM_METHOD_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  IF lower(coalesce(v_booking.status, '')) = 'confirmed' THEN
    IF v_booking.payout_status = 'pending'
       AND v_booking.host_payout_amount IS NOT NULL
       AND v_booking.platform_revenue IS NOT NULL THEN
      RETURN QUERY SELECT 'already_processed'::text;
      RETURN;
    END IF;
    RAISE EXCEPTION 'BANK_CONFIRM_STORED_RESULT_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  IF lower(coalesce(v_booking.status, '')) <> 'pending' THEN
    RAISE EXCEPTION 'BANK_CONFIRM_STATUS_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  v_solo_net := greatest(
    0,
    coalesce(v_booking.solo_guarantee_price, 0)
      - coalesce(v_booking.solo_guarantee_refund_amount, 0)
  );
  v_refund_liability := greatest(
    coalesce(v_booking.refund_amount, 0),
    coalesce(v_booking.solo_guarantee_refund_amount, 0)
  );
  v_total_experience := CASE
    WHEN coalesce(v_booking.total_experience_price, 0) > 0
      THEN v_booking.total_experience_price
    WHEN coalesce(v_booking.total_price, 0) > 0
      THEN v_booking.total_price
    ELSE v_booking.amount
  END;
  v_base_price := CASE
    WHEN coalesce(v_booking.price_at_booking, 0) > 0
      THEN v_booking.price_at_booking
    ELSE greatest(0, v_total_experience - v_solo_net)
  END;
  v_host_payout := CASE
    WHEN coalesce(v_booking.host_payout_amount, 0) > 0
      THEN v_booking.host_payout_amount
    ELSE floor(v_total_experience * 0.8)::integer
  END;
  v_platform_revenue := CASE
    WHEN coalesce(v_booking.platform_revenue, 0) > 0
      THEN v_booking.platform_revenue
    ELSE greatest(0, v_booking.amount - v_refund_liability - v_host_payout)
  END;

  UPDATE public.bookings
     SET status = 'confirmed',
         price_at_booking = v_base_price,
         total_experience_price = v_total_experience,
         host_payout_amount = v_host_payout,
         platform_revenue = v_platform_revenue,
         payout_status = 'pending'
   WHERE id = v_booking.id;

  RETURN QUERY SELECT 'confirmed_now'::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_experience_payment_atomic(p_booking_id text, p_provider text, p_provider_reference text, p_provider_transaction_id text, p_verified_amount integer)
 RETURNS TABLE(outcome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_provider text := lower(btrim(coalesce(p_provider, '')));
  v_reference text := nullif(btrim(coalesce(p_provider_reference, '')), '');
  v_tid text := nullif(btrim(coalesce(p_provider_transaction_id, '')), '');
  v_max_guests integer;
  v_current_booked integer;
  v_has_private boolean;
  v_total_experience numeric;
  v_base_price numeric;
  v_host_payout integer;
  v_platform_revenue integer;
  v_refund_liability integer;
  v_solo_net integer;
  v_slot_key text;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  IF v_provider = '' OR v_reference IS NULL OR v_tid IS NULL
     OR p_verified_amount IS NULL OR p_verified_amount <= 0 THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_BAD_REQUEST' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_booking
    FROM public.bookings
   WHERE id = p_booking_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  IF lower(coalesce(v_booking.status, '')) IN ('paid', 'confirmed', 'completed') THEN
    IF v_booking.payment_claim_state = 'completed'
       AND v_booking.payment_provider = v_provider
       AND v_booking.payment_provider_reference = v_reference
       AND v_booking.tid = v_tid THEN
      RETURN QUERY SELECT 'already_processed'::text;
      RETURN;
    END IF;
    RAISE EXCEPTION 'PAYMENT_CONFIRM_ALREADY_PROCESSED_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  IF lower(coalesce(v_booking.status, '')) <> 'pending'
     OR v_booking.tid IS NOT NULL THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_STATUS_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  IF (lower(coalesce(v_booking.payment_method, '')) = 'paypal' AND v_provider <> 'paypal')
     OR (lower(coalesce(v_booking.payment_method, '')) = 'card' AND v_provider NOT IN ('nicepay', 'portone'))
     OR lower(coalesce(v_booking.payment_method, '')) NOT IN ('card', 'paypal') THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_METHOD_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  IF v_booking.payment_provider IS DISTINCT FROM v_provider
     OR v_booking.payment_provider_reference IS DISTINCT FROM v_reference
     OR v_booking.payment_claim_state NOT IN ('processing', 'reconciliation_required') THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_ATTEMPT_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  IF v_booking.amount IS DISTINCT FROM p_verified_amount THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_AMOUNT_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  v_slot_key := format('%s|%s|%s', v_booking.experience_id, v_booking.date, v_booking.time);
  PERFORM pg_advisory_xact_lock(hashtext(v_slot_key)::bigint);

  SELECT coalesce(e.max_guests, 10)
    INTO v_max_guests
    FROM public.experiences e
   WHERE e.id = v_booking.experience_id;

  IF v_max_guests IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_EXPERIENCE_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  SELECT
    coalesce(sum(b.guests), 0)::integer,
    coalesce(bool_or(b.type = 'private'), false)
  INTO v_current_booked, v_has_private
  FROM public.bookings b
  WHERE b.experience_id = v_booking.experience_id
    AND b.date = v_booking.date
    AND b.time = v_booking.time
    AND b.id <> v_booking.id
    AND lower(b.status) IN ('paid', 'confirmed');

  IF v_has_private
     OR (v_booking.type = 'private' AND v_current_booked > 0)
     OR (v_booking.type <> 'private' AND v_current_booked + coalesce(v_booking.guests, 0) > v_max_guests) THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRM_CAPACITY_CONFLICT' USING ERRCODE = 'P0001';
  END IF;

  v_solo_net := greatest(
    0,
    coalesce(v_booking.solo_guarantee_price, 0)
      - coalesce(v_booking.solo_guarantee_refund_amount, 0)
  );
  v_refund_liability := greatest(
    coalesce(v_booking.refund_amount, 0),
    coalesce(v_booking.solo_guarantee_refund_amount, 0)
  );
  v_total_experience := CASE
    WHEN coalesce(v_booking.total_experience_price, 0) > 0
      THEN v_booking.total_experience_price
    WHEN coalesce(v_booking.total_price, 0) > 0
      THEN v_booking.total_price
    ELSE v_booking.amount
  END;
  v_base_price := CASE
    WHEN coalesce(v_booking.price_at_booking, 0) > 0
      THEN v_booking.price_at_booking
    ELSE greatest(0, v_total_experience - v_solo_net)
  END;
  v_host_payout := CASE
    WHEN coalesce(v_booking.host_payout_amount, 0) > 0
      THEN v_booking.host_payout_amount
    ELSE floor(v_total_experience * 0.8)::integer
  END;
  v_platform_revenue := CASE
    WHEN coalesce(v_booking.platform_revenue, 0) > 0
      THEN v_booking.platform_revenue
    ELSE greatest(0, v_booking.amount - v_refund_liability - v_host_payout)
  END;

  UPDATE public.bookings
     SET status = 'PAID',
         tid = v_tid,
         price_at_booking = v_base_price,
         total_experience_price = v_total_experience,
         host_payout_amount = v_host_payout,
         platform_revenue = v_platform_revenue,
         payout_status = 'pending',
         payment_claim_state = 'completed',
         payment_claim_expires_at = NULL,
         payment_claim_token = NULL
   WHERE id = v_booking.id;

  RETURN QUERY SELECT 'confirmed_now'::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_booking_atomic(p_user_id uuid, p_experience_id text, p_date text, p_time text, p_guests integer, p_is_private boolean, p_customer_name text, p_customer_phone text, p_payment_method text DEFAULT 'card'::text, p_is_solo_guarantee boolean DEFAULT false)
 RETURNS TABLE(new_order_id text, final_amount numeric, host_id text, experience_title text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_experience_id public.experiences.id%TYPE;
  v_host_id text;
  v_title text;
  v_price numeric;
  v_private_price numeric;
  v_max_guests integer;
  v_solo_guarantee_unit_price numeric;
  v_guest_count integer;
  v_base_host_price numeric;
  v_host_price numeric;
  v_fee numeric;
  v_final_amount numeric;
  v_current_booked integer;
  v_has_private_booking boolean;
  v_confirmed_booked integer;
  v_has_confirmed_private_booking boolean;
  v_slot_key text;
  v_new_order_id text;
  v_booking_date date;
  v_booking_time_text text;
  v_solo_guarantee_price numeric;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'BOOKING_FORBIDDEN:Server-only function' USING ERRCODE = 'P0001';
  END IF;

  IF p_user_id IS NULL
     OR coalesce(btrim(p_experience_id), '') = ''
     OR coalesce(btrim(p_date), '') = ''
     OR coalesce(btrim(p_time), '') = ''
     OR coalesce(btrim(p_customer_name), '') = ''
     OR coalesce(btrim(p_customer_phone), '') = '' THEN
    RAISE EXCEPTION 'BOOKING_BAD_REQUEST:Missing required fields' USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    v_booking_date := p_date::date;
    v_booking_time_text := to_char(p_time::time, 'HH24:MI');
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'BOOKING_BAD_REQUEST:Invalid date/time format' USING ERRCODE = 'P0001';
  END;

  SELECT e.id, e.host_id::text, e.title, coalesce(e.price, 0),
         coalesce(e.private_price, 0), coalesce(e.max_guests, 10),
         coalesce(e.solo_guarantee_price, 30000)
    INTO v_experience_id, v_host_id, v_title, v_price, v_private_price,
         v_max_guests, v_solo_guarantee_unit_price
    FROM public.experiences e
   WHERE e.id::text = p_experience_id
   LIMIT 1;

  IF v_experience_id IS NULL THEN
    RAISE EXCEPTION 'BOOKING_NOT_FOUND:Experience not found' USING ERRCODE = 'P0001';
  END IF;

  v_guest_count := greatest(coalesce(p_guests, 0), 1);
  v_slot_key := format('%s|%s|%s', v_experience_id, v_booking_date, v_booking_time_text);
  PERFORM pg_advisory_xact_lock(hashtext(v_slot_key)::bigint);

  UPDATE public.bookings b
     SET status = 'cancelled',
         cancel_reason = '카드 결제 미완료 (30분 경과 자동 취소)',
         refund_amount = 0
   WHERE b.experience_id = v_experience_id
     AND b.date = v_booking_date
     AND b.time = v_booking_time_text
     AND lower(b.status) = 'pending'
     AND lower(coalesce(b.payment_method, '')) = 'card'
     AND b.tid IS NULL
     AND b.created_at < now() - interval '30 minutes'
     AND b.payment_claim_state IS NULL;

  SELECT coalesce(sum(b.guests), 0)::integer,
         coalesce(bool_or(b.type = 'private'), false)
    INTO v_current_booked, v_has_private_booking
    FROM public.bookings b
   WHERE b.experience_id = v_experience_id
     AND b.date = v_booking_date
     AND b.time = v_booking_time_text
     AND lower(b.status) IN ('pending', 'paid', 'confirmed');

  IF v_has_private_booking
     OR (p_is_private AND v_current_booked > 0)
     OR ((NOT p_is_private) AND (v_current_booked + v_guest_count > v_max_guests)) THEN
    RAISE EXCEPTION 'BOOKING_CONFLICT:해당 시간대에 남은 좌석이 부족합니다.' USING ERRCODE = 'P0001';
  END IF;

  IF coalesce(p_is_solo_guarantee, false) AND (p_is_private OR v_guest_count <> 1) THEN
    RAISE EXCEPTION 'BOOKING_BAD_REQUEST:Solo guarantee is only available for shared solo bookings' USING ERRCODE = 'P0001';
  END IF;

  SELECT coalesce(sum(b.guests), 0)::integer,
         coalesce(bool_or(b.type = 'private'), false)
    INTO v_confirmed_booked, v_has_confirmed_private_booking
    FROM public.bookings b
   WHERE b.experience_id = v_experience_id
     AND b.date = v_booking_date
     AND b.time = v_booking_time_text
     AND lower(b.status) IN ('paid', 'confirmed');

  IF coalesce(p_is_solo_guarantee, false)
     AND (v_confirmed_booked > 0 OR v_has_confirmed_private_booking) THEN
    RAISE EXCEPTION 'BOOKING_BAD_REQUEST:Solo guarantee is unavailable when confirmed bookings already exist' USING ERRCODE = 'P0001';
  END IF;

  v_solo_guarantee_price := CASE
    WHEN coalesce(p_is_solo_guarantee, false) AND NOT p_is_private AND v_guest_count = 1
      THEN v_solo_guarantee_unit_price
    ELSE 0
  END;
  v_base_host_price := CASE WHEN p_is_private THEN v_private_price ELSE v_price * v_guest_count END;
  v_host_price := v_base_host_price + v_solo_guarantee_price;
  v_fee := floor(v_base_host_price * 0.1);
  v_final_amount := v_host_price + v_fee;

  LOOP
    v_new_order_id := format(
      'ORD-%s-%s',
      to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'),
      lpad((floor(random() * 1000))::integer::text, 3, '0')
    );
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.bookings b
       WHERE b.order_id = v_new_order_id OR b.id = v_new_order_id
    );
  END LOOP;

  INSERT INTO public.bookings (
    id, order_id, user_id, experience_id, amount, total_price, status,
    guests, date, time, type, contact_name, contact_phone, message,
    created_at, payment_method, is_solo_guarantee, solo_guarantee_price
  ) VALUES (
    v_new_order_id, v_new_order_id, p_user_id, v_experience_id,
    v_final_amount, v_host_price, 'PENDING', v_guest_count, v_booking_date,
    v_booking_time_text, CASE WHEN p_is_private THEN 'private' ELSE 'group' END,
    p_customer_name, p_customer_phone, '', now(), coalesce(p_payment_method, 'card'),
    v_solo_guarantee_price > 0, v_solo_guarantee_price::integer
  );

  RETURN QUERY SELECT v_new_order_id, v_final_amount, v_host_id, coalesce(v_title, 'Locally 체험');
END;
$function$
